def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, val in grid_values:
        grid[x][y] = val

    # Bottom-up dynamic programming
    for i in range(1, N):
        for j in range(1, N):
            grid[i][j] = max(grid[i-1][j], grid[i][j-1]) + grid[i][j]

    # Paths from the top-left corner to the bottom-right corner
    top_path = []
    right_path = []
    x, y = N-1, N-1
    while x >= 0 and y >= 0:
        top_path.append((x, y))
        right_path.append((x, y))
        if x > 0:
            x -= 1
        if y < N-1:
            y += 1

    # Calculate the maximum sum on each path
    max_sum_top = 0
    max_sum_right = 0
    for x, y in top_path:
        max_sum_top += grid[x][y]
    for x, y in right_path:
        max_sum_right += grid[x][y]

    return max(max_sum_top, max_sum_right)

def find_number_combinations() -> List[Tuple[int, int, int]]:
    def is_valid_pair(x: int, y: int) -> bool:
        return y == 2 * x

    def is_valid_triple(x: int, y: int, z: int) -> bool:
        return z == 3 * x

    numbers = set(range(1, 10))

    pairs = [(x, y) for x in numbers for y in numbers if is_valid_pair(x, y)]

    triplets = [(x, y, z) for x in numbers for y, z in pairs if is_valid_triple(x, y, z)]

