def max_product(num_str: str, N: int, K: int) -> int:
    if len(num_str) < N + K + 1:
        return 0

    num_list = list(num_str)

    # Calculate the initial density of 1's
    while K > 0 and 1 in num_list:
        nb_ones = num_list.count('1')
        if nb_ones > 0:
            for i in range(nb_ones - 1):
                num_list[i] = '1'
            num_list[nb_ones - 2] = '*'
            K -= 1

    # Check if the density of 1's is sufficient
    if K > len(num_list) - 1:
        return 0

    # Calculate the product of the maximum product
    max_product = 1
    for i in range(N):
        max_product *= int(num_list[i])

    # Append the rest of the numbers after the multiplication signs
    max_product *= int(''.join(num_list[K:]))

    return max_product

def max_product(num_str, N, K):
    x = float('-inf') if K < 0 else -float('inf')
    for i in range(1, N - K + 1):
        y = float('-inf') if K == 0 else -float('inf')
        j, k = 0, 0
        while j < i:
            y = max(y, float(num_str[j]))
            j += 1
        while k < N - i:
            x = max(x, float(num_str[k]))
            k += 1
        for c in range(i, N - K + 1):
            if num_str[c] == '*':
                y *= x
            else:
                y *= float(num_str[c])
        x = max(x, y)
    return int(x)

def max_product(num_str: str, N: int, K: int) -> int:
    import math

    # Check if the number of multiplication signs is within the limit
    if K > len(num_str) - 1:
        raise ValueError("K must be less than or equal to the length of the number string minus one.")

    # Iterate through all possible positions to insert multiplication signs
    max_product = 0
    for i in range(len(num_str)):
        # If the current position is even, add multiplication sign
        if i % 2 == 0:
            result = float(num_str[0:i]) * float(num_str[i+1:])
        else:
            result = float(num_str[0:i+1]) * float(num_str[i])
