def verify_isbn(isbn: str) -> str:
    defisbn_standard_checksum(original_isbn) -> int:
        digits = [i) for i in original_isbn if i.isdigit()]
        sum = 0
        for i, digit in enumerate(reversed(digits)):
            if (i + 1) % 2 == 0:
                sum += 3 * int(digit)
            else:
                sum += int(digit)
        return sum % 10

    if not isbn[0].isdigit() or not isbn[-1] in ['X', 'x']:
        return f"Invalid ISBN format. Ensure it starts with a digit and ends with 'X' or 'x'."

    recvd = isbn[0:-1].upper()
    calc = isbn_standard_checksum(recvd)
    if calc == int(isbn[-1]) if isbn[-1].isdigit() else 10:  # Check for an 'X' in a normal position or a digit for a checksum position
        return "Right"
    else:
        return f"Wrong. Corrected ISBN: {recvd[:-1]}{calc}"

