        return 0

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        return 0

    # Initialize a DP table
    dp = [[0] * n for _ in range(m + 1)]

    # Base case: For one pass, each student has 2 choices
    for i in range(n):
        dp[1][i] = 2

    # Fill the DP table for each pass
    for pass_num in range(2, m + 1):
        for j in range(n):
            # The ball can move to the left neighbor or right neighbor
            dp[pass_num][j] = (dp[pass_num - 1][(j - 1) % n] + dp[pass_num - 1][(j + 1) % n]) % (10**10)

    # The number of ways to return to the starting student after m passes
    return dp[m][(0 - 1) % n]

def count_passing_ways(n: int, m: int) -> int:
    def factorial(k):
        result = 1
        for i in range(1, k + 1):
            result *= i
        return result

    left_to_right = factorial(n - 1)
    right_to_left = factorial(n - 1)
    total_ways = (right_to_left + left_to_right) % 1000000007

    for _ in range(m - 1):
        total_ways = (total_ways * (left_to_right + right_to_left)) % 1000000007

    return total_ways

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        raise ValueError("Number of students and number of passes must be positive integers.")

    # Initialize a 2D array with zeros
    dp = [[0] * (m + 1) for _ in range(n)]

    # Define base cases
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp array
    for i in range(n):
        for j in range(1, m + 1):
            dp[i][j] = (dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]) % 1000000007

    return dp[0][m]

