def max_energy(beads):
    n = len(beads)

    # Create a dp array to store the maximum energy up to each element
    dp = [0] * n

    # Iterate through each element in the necklace
    for i in range(n):
        # Iterate through each previous element to find a matching head-tail pair
        for j in range(i):
            if beads[j] == beads[i]:
                # Calculate energy for the current pair
                if i == j:  # On the first element itself
                    dp[i] = beads[i] ** 3
                else:
                    dp[i] = dp[j] * dp[(i-1+j)%n] * beads[i]

    # The maximum energy is the maximum value in the dp array
    return max(dp)

def max_energy(beads):
    n = len(beads)
    gdp = [[0 for _ in range(n)] for _ in range(n)]

    # Fill dp table entries for non-overlapping pairs
    for i in range(n):
        gdp[i][i] = beads[i]

    # Fill the dp table for overlapping pairs
    for l in range(2, n + 1):  # length of subsequence
        for i in range(0, n - l + 1):  # starting index of subsequence
            j = i + l - 1  # ending index of subsequence
            for k in range(i, j):
                head_gdp = gdp[k][i] if k != 0 else 0
                tail_gdp = gdp[j][k + 1] if k + 1 != n else 0
                if beads[j] == beads[k]:
                    gdp[i][j] = max(gdp[i][j], head_gdp * beads[j] * tail_gdp)

                # Update the maximum energy for the current subsequence length
                for r in range(i, k):
                    if beads[k] == beads[r]:
                        gdp[i][j] = max(gdp[i][j], gdp[i][r] * beads[r] * beads[j])

    return gdp[0][n - 1]

