        dp[i][i-1] = beads[i-1] * beads[i] * beads[0]

    for length in range(3, n+1):
        for left in range(n-length+1):
            right = left + length - 1
            for k in range(left+1, right):
                dp[left][right] = max(dp[left][right], 
                                      dp[left][k] * dp[k][right] * beads[left])

    return dp[0][n-1]

