def largest_prime_factor(n: int) -> int:
    # Check if n is a prime number itself
    if n <= 1:
        return None

    # Divide n by 2 to remove all even factors
    while n % 2 == 0:
        n //= 2

    # Start checking from the smallest prime number 3
    factor = 3
    while factor <= math.sqrt(n):
        # If factor is a factor of n, divide n and update factor
        while n % factor == 0:
            n //= factor
        factor += 2

    # If n is a prime number greater than 2, then n itself is the largest prime factor
    if n > 2:
        return n
    else:
        return None

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        return None  # naively largest prime factor is greater than 1
    if n <= 3:
        return n  # if n is 2 or 3, it's prime

    prime = 2
    while prime * prime <= n:
        if n % prime:
            prime += 1
        else:
            n //= prime
    return n if n > 1 else prime  # n must now be prime

