    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    # Base case: there is one way to partition 0 into 0 number of parts
    for j in range(1, k + 1):
        dp[0][j] = 1

    # Fill the DP table
    for part in range(1, n + 1):
        for num_parts in range(1, min(part, k) + 1):
            if part - num_parts * x >= x:
                dp[part][num_parts] = dp[part - num_parts * x][num_parts - 1] + dp[part][num_parts]

    return dp[n][k]

