def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    root_val = postorder[-1]
    root_index = inorder.index(root_val)

    left_inorder = inorder[:root_index]
    right_inorder = inorder[root_index + 1:]

    left_postorder = postorder[:root_index]
    right_postorder = postorder[root_index:-1]

    return root_val + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

def preorder_traversal(inorder: str, postorder: str) -> str:
    def build_tree(inorder, postorder):
        if not inorder or not postorder:
            return None

        root = TreeNode(postorder[-1])
        index = inorder.index(postorder[-1])

        root.left = build_tree(inorder[:index], postorder[:index])
        root.right = build_tree(inorder[index + 1:], postorder[index:-1])

        return root

    def reconstruct_preorder(root):
        if not root:
            return

        preorder.append(root.val)
        reconstruct_preorder(root.left)
        reconstruct_preorder(root.right)

    preorder = []
    root = build_tree(inorder, postorder)
    reconstruct_preorder(root)
    return ''.join(map(str, preorder))

