def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    Args:
    - T (int): The total time available for picking herbs.
    - M (int): The number of different herbs in the cave.
    - herbs (List[Tuple[int, int]]): A list of tuples, where each tuple contains two integers
      representing the time required to pick the herb and the herb's value, respectively.

    Returns:
    - int: The maximum total value of herbs that can be picked within the time limit.
    """
    if not herbs or T <= 0 or M <= 0:
        return 0

    wisdom = [[] for _ in range(M)]

    for herb in herbs:
        if herb[0] <= T:
            wisdom[herb[1] - 1].append(herb[1])

    dp = [[0] * (T + 1) for _ in range(M)]

    for i in wisdom:
        for j in range(T + 1):
            for k in i:
                dp[k][j] = max(dp[k][j], dp[k - k][j - herb[1]] + herb[1])

    return dp[T][T]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    n = len(herbs)
    table = [[0 for _ in range(T + 1)] for _ in range(M + 1)]

    for i in range(1, M + 1):
        for j in range(1, T + 1):
            if herbs[i-1][0] <= j:
                table[i][j] = max(table[i-1][j], herbs[i-1][1] + table[i-1][j-herbs[i-1][0]])
            else:
                table[i][j] = table[i-1][j]

    return table[M][T]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    n = len(herbs)
    dp = [[-1 for _ in range(T + 1)] for _ in range(n + 1)]

    for i in range(1, n + 1):
        t, v = herbs[i - 1]
        for j in range(1, T + 1):
            if t > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], v + dp[i - 1][j - t])

    return dp[n][T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V <= 0 or n <= 0 or len(volumes) < n:
        return "Invalid input"

    dp = [(0,) * (V + 1)] * n

    for i in range(n):
        for j in range(V + 1):
            if j >= volumes[i]:
                dp[i + 1][j] = max(dp[i][j], dp[i][j - volumes[i]] + volumes[i])
            else:
                dp[i + 1][j] = dp[i][j]

    max_occupied_volume = max(dp[n])
    min_remaining_space = V - max_occupied_volume
    return min_remaining_space

