def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Define a DP table to keep track of the maximum volume in each state
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Initialize base cases
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            # If the current item can fit into the current state, include it
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i][j], max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1]))
            else:
                dp[i][j] = dp[i - 1][j]

    # The minimum remaining space is the difference between box capacity and the maximum occupied volume
    return V - dp[n][V]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    def tree_sum(arr, i=0, j=len(arr) - 1) -> tuple[int, int]:
        if j < i:
            return (0, 1)
        mid = (i + j) // 2
        left, right = tree_sum(arr, i, mid), tree_sum(arr, mid + 1, j)
        s = arr[mid]
        return (left[0] + right[0], left[1] * right[0] + right[1] * left[0] + (s * (mid - i + 1)) % MOD)

    def catalan(n) -> int:
        if n < 0:
            return 0
        a = [1] * (n + 1)
        for i in range(2, n + 1):
            for j in range(1, i + 1):
                a[i] = (a[i] + a[j - 1] * a[i - j]) % MOD
        return a[-1]

    counter = [0] * (m + 1)
    counter[0] = 1

    for r in range(m + 1):
        sum, comb = tree_sum(a)
        counter[r] = comb * catalan(sum) % MOD

    return sum % MOD

