def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7

    # Check if the input is valid
    if n <= 0 or m <= 0 or len(a) != n or any(x < 0 for x in a):
        raise ValueError("Invalid input parameters")

    # Precompute the factorials for efficient calculation
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    # Dynamic programming to calculate the number of arrangements
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][0] = 1  # There is exactly one way to arrange 0 pots

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(1, a[i-1] + 1):
                if k * a[i-1] <= j:
                    dp[i][j] = (dp[i][j] + dp[i-1][j - k * a[i-1]] % MOD) % MOD

    return dp[n][m]

