def mod_inverse(a, b):
    if b == 0:
        return None

    x0, x1 = 1, 0
    y0, y1 = 0, 1

    while b:
        q = a // b
        a, b = b, a % b

        x0, x1 = x1 - q * x0, x0
        y0, y1 = y1 - q * y1, y1

    if x0 < 0:
        x0 += b

    return x0

def mod_inverse(a, b):
    if b == 0:
        return "Error: Modulus cannot be zero."
    x0, x1 = 1, 0
    y0, y1 = 0, 1

    while b != 0:
        quotient = a // b
        a, b = b, a % b
        x0, x1 = x1, x0 - quotient * x1
        y0, y1 = y1, y0 - quotient * y1

    if a != 1:
        return None
    return x0 % b

